--
-- Structure for view `v_game_generation_stats`
--
DROP TABLE IF EXISTS `v_game_generation_stats`;

CREATE ALGORITHM=UNDEFINED DEFINER=`pwm`@`%` SQL SECURITY DEFINER VIEW `v_game_generation_stats`  AS SELECT count(distinct `pp`.`PlayerPairId`) AS `total_pairs`, count(distinct `pg`.`PairGameId`) AS `total_games`, count(distinct (case when (`pg`.`IsActive` = 1) then `pg`.`PairGameId` end)) AS `active_games`, count(distinct (case when (`pg`.`IsFinished` = 1) then `pg`.`PairGameId` end)) AS `finished_games`, avg(timestampdiff(HOUR,`pg`.`Timestamp`,now())) AS `avg_hours_since_game_start` FROM (`net_playerpair` `pp` left join `net_pairgame` `pg` on((`pp`.`PlayerPairId` = `pg`.`PlayerPairId`))) WHERE (`pp`.`IsActive` = 1) ;

-- --------------------------------------------------------

--
-- Structure for view `v_pair_generation_performance`
--
DROP TABLE IF EXISTS `v_pair_generation_performance`;

CREATE ALGORITHM=UNDEFINED DEFINER=`pwm`@`%` SQL SECURITY DEFINER VIEW `v_pair_generation_performance`  AS SELECT `pp`.`PlayerPairId` AS `PlayerPairId`, `pp`.`Player1` AS `Player1`, `pp`.`Player2` AS `Player2`, count(`pg`.`PairGameId`) AS `games_count`, max(`pg`.`Timestamp`) AS `last_game_time`, timestampdiff(HOUR,max(`pg`.`Timestamp`),now()) AS `hours_since_last_game` FROM (`net_playerpair` `pp` left join `net_pairgame` `pg` on((`pp`.`PlayerPairId` = `pg`.`PlayerPairId`))) WHERE (`pp`.`IsActive` = 1) GROUP BY `pp`.`PlayerPairId`, `pp`.`Player1`, `pp`.`Player2` ORDER BY `games_count` DESC, `last_game_time` DESC ;

