INSERT INTO `net_taskanswer` (`Id`, `OrderNumber`, `CompletedTaskId`, `AttachedText`, `AnswerText`, `MediaPath`, `Timestamp`, `Score`, `Offensive`) VALUES
(2025, 0, 2025, 'אתם בדייט עכשיו. איזה חיסרון שלכם תנסו להצניע?', '<b>1</b>', NULL, '2025-09-05 09:07:37', NULL, NULL),
(2031, 0, 2031, 'איפה אתה חולםת להתחתן? ', '<span class=\'task-answer-text\'>אולם אירועים מפואר </span><b>לא</b><span class=\'task-answer-text\'>,  גן אירועים </span><b>לא</b><span class=\'task-answer-text\'>, ביער נידח בארגון עצמי </span><b>כן</b><span class=\'task-answer-text\'>, לאס וגאס </span><b>כן</b><span class=\'task-answer-text\'>, חתונה צנועה בגינה של ההורים</span>', NULL, '2025-10-30 20:03:46', NULL, NULL),
(2032, 0, 2032, 'ספרו על סלב כלשהו שהערצתם כילד ועכשיו אתם מרגישים שזה היה מגוחך?', '<b>שחקני כדורסל</b>', NULL, '2025-10-30 20:12:23', NULL, NULL),
(2033, 0, 2033, 'ספרו על סלב כלשהו שהערצתם כילד ועכשיו אתם מרגישים שזה היה מגוחך?', '<b>בת הים הקטנה</b>', NULL, '2025-10-30 20:12:48', NULL, NULL),
(2034, 0, 2034, 'איך אתם מעבירים את הזמן כשאתם לבד בבית בערב אחרי יום עבודה מתיש?', '<b>פותח נטפליקס ונרדם אחרי המסך של הלוגו</b>', NULL, '2025-10-30 20:17:12', NULL, NULL),
(2035, 0, 2035, 'איך אתם מעבירים את הזמן כשאתם לבד בבית בערב אחרי יום עבודה מתיש?', '<b>מחפשת באינטרנט חופשות אקסטרים</b>', NULL, '2025-10-30 20:20:04', NULL, NULL),
(2036, 0, 2036, 'כשהיית בזוגיות, עד כמה הרגשת  פתוחה לדבר על היחסים הזוגיים שלך עם חברים או משפחה?', '<b>אין בעיה. חופשי</b>', NULL, '2025-10-30 20:27:18', NULL, NULL),
(2037, 0, 2037, 'כשהיית בזוגיות, עד כמה הרגשת  פתוחה לדבר על היחסים הזוגיים שלך עם חברים או משפחה?', '<b>לא בשלב הראשון</b>', NULL, '2025-10-30 20:27:53', NULL, NULL),
(2038, 0, 2038, 'עד כמה רומנטי כל דבר בעיניך: ', '<span class=\'task-answer-text\'>עד כמה רומנטי? סביב למדורה עם גיטרה </span><b>פחחח</b><span class=\'task-answer-text\'>, צפיה במיטה בסדרה אהובה </span><b>בול</b><span class=\'task-answer-text\'>, בניית רהיט של איקאה ביחד </span><b>השתגעת?</b><span class=\'task-answer-text\'>, </span>', NULL, '2025-10-30 20:28:29', NULL, NULL),
(2040, 0, 2040, 'אתם בדייט עכשיו. איזה חיסרון שלכם תנסו להצניע?', '<b>Gg</b>', NULL, '2025-11-04 07:29:57', NULL, NULL),
(2054, 0, 2054, 'איזו מנה עיקרית אתם הכי אוהבים לאכול?', '<b>סטייק</b>', NULL, '2025-11-12 13:16:22', NULL, NULL),
(2055, 0, 2055, 'האם השתתפת פעם בתחרות ספורט עם מדליה או גביע? האם זכית פעם? אם כן, במה?', '<b>כן, זכיתי במדליה בשחייה.</b>', NULL, '2025-11-12 13:17:42', NULL, NULL),
(2063, 0, 2063, 'מהו הדייט השני האידיאלי בעיניך?', '<span class=\'task-answer-text\'>פיקניק רומנטי בפארק - </span><b>בשקיעה</b><span class=\'task-answer-text\'>,  סרט קולנוע - </span><b>דרמה קומית</b><span class=\'task-answer-text\'>, צניחה חופשית - </span><b>מעל הים</b><span class=\'task-answer-text\'>, הליכה ספורטיבית - </span><b>בטבע</b><span class=\'task-answer-text\'>, בית קפה - </span><b>בכיף</b>', NULL, '2025-11-12 14:53:47', NULL, NULL);
